F=R/'15_figures';ledger=[]
def save(fig,num,name,caption):
 fig.suptitle(f'C02 | R8-E10-R2 | {name}',fontsize=13);fig.tight_layout(rect=(0,0,1,.95));stem=f'{num:02d}_'+name.replace(' ','_').replace('/','_');fig.savefig(F/(stem+'.png'));fig.savefig(F/(stem+'.pdf'));plt.close(fig);ledger.append(dict(number=num,title=name,PNG='15_figures/'+stem+'.png',PDF='15_figures/'+stem+'.pdf',caption=caption));print('FIGURE',num,name,flush=True)
def mapfig(x,tri,val,title,label='MPa',cmap='viridis',limits=None):
 fig,ax=plt.subplots(figsize=(10,5));t=mtri.Triangulation(x[:,0],x[:,1],tri);t.set_mask(np.any(~np.isfinite(val[tri]),axis=1));kw={} if limits is None else dict(vmin=limits[0],vmax=limits[1]);c=ax.tripcolor(t,val,shading='gouraud',cmap=cmap,**kw);fig.colorbar(c,ax=ax,label=label);ax.set(xlabel='Global X [mm]',ylabel='Global Y [mm]',title=title);ax.set_aspect('equal');return fig
def textfig(title,lines):
 fig,ax=plt.subplots(figsize=(10,5));ax.axis('off');ax.text(.03,.95,title+'\n\n'+'\n'.join(lines),va='top',transform=ax.transAxes,fontfamily='monospace',fontsize=10);return fig
